function cheapestLeveling(nums: number[], cost: number[]): number {
  const f = (x: number): number => {
    let total = 0;
    for (let i = 0; i < nums.length; i++) total += Math.abs(nums[i] - x) * cost[i];
    return total;
  };
  let lo = nums.reduce((a, b) => Math.min(a, b)), hi = nums.reduce((a, b) => Math.max(a, b));
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (f(mid) <= f(mid + 1)) hi = mid; // bottom is at mid or to its left
    else lo = mid + 1;
  }
  return f(lo);
}

