function cheapestLeveling(nums: number[], cost: number[]): number {
  const idx = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b]);
  const total = cost.reduce((s, c) => s + c, 0);
  let run = 0, target = nums[idx[0]];
  for (const i of idx) {
    run += cost[i];
    if (2 * run >= total) { target = nums[i]; break; }
  }
  let answer = 0;
  for (let i = 0; i < nums.length; i++) answer += Math.abs(nums[i] - target) * cost[i];
  return answer;
}

